local KTool = CS.Engine.Lib.KTool
local NewChapterConstants = import("Game.Chapter.NewChapterConstants")
local SettingMgr = SettingMgr:GetInstance()
local Yielders = CS.Engine.Lib.Yielders
local cs_coroutine = require 'XLua.cs_coroutine'
--- from: Assets/BundleResources/Prefabs/ChapterNew/ChapterNormal.prefab
---@class ChapterLoading
---@field Env                           	ChapterLoading                          
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field TextDay                       	UnityEngine.RectTransform               
---@field RandomTime3                   	UnityEngine.RectTransform               
---@field RandomTime2                   	UnityEngine.RectTransform               
---@field RandomTime1                   	UnityEngine.RectTransform               
---@field DayNumber                     	UnityEngine.RectTransform               
---@field SecondPhase                   	UnityEngine.RectTransform               
---@field FirstPhase                    	UnityEngine.RectTransform               
---@field FirstTime2                    	UnityEngine.RectTransform               
---@field FirstTime1                    	UnityEngine.RectTransform               
---@field FirstTitle                    	UnityEngine.RectTransform               
local ChapterLoading = Class('ChapterLoading')
local randomTimeCount = 3

function ChapterLoading:__init()
    
end

function ChapterLoading:__delete()
    
end

function ChapterLoading:Awake()
    self:InitNode()
    self.LoadingVo = SettingMgr:GetSetting(AutoIds.IdSetting4105, "ChapterLoadingVo")
end

function ChapterLoading:InitNode()
    KTool.SetActive(self.FirstPhase.gameObject,false)
    KTool.SetActive(self.SecondPhase.gameObject,false)
end

function ChapterLoading:Start()
end

function ChapterLoading:RefreshShow(vo)
    KTool.SetActive(self.FirstPhase.gameObject,vo.type == NewChapterConstants.NewType.LoadingFirst)
    KTool.SetActive(self.SecondPhase.gameObject,vo.type == NewChapterConstants.NewType.LoadingSecond)
    local loadingVo = self.LoadingVo:Get(vo.sceneId)
    if not isNull(loadingVo) then
        if vo.type == NewChapterConstants.NewType.LoadingFirst then
            CfUtils.FillText(self.FirstTitle,loadingVo.location)
            CfUtils.FillText(self.FirstTime1,loadingVo.day)
            CfUtils.FillText(self.FirstTime2,loadingVo.hour)
            coroutine.yield(Yielders.GetWaitForSeconds(2))
            KTool.SetActive(self.FirstPhase.gameObject,false)
        elseif vo.type == NewChapterConstants.NewType.LoadingSecond then
            self:StopCo()
            self:SetTextDay(loadingVo.prechangeId)
            self.changeCo = cs_coroutine.start(function()
                CfUtils.FillText(self.DayNumber,loadingVo.prechangeId)
                coroutine.yield(Yielders.GetWaitForSeconds(1.5))
                self:SetTextDay(loadingVo.postchangeId)
                CfUtils.FillText(self.DayNumber,loadingVo.postchangeId)
            end)
            self:SetRandomTime()
            coroutine.yield(Yielders.GetWaitForSeconds(3.5))
            KTool.SetActive(self.SecondPhase.gameObject,false)
        else
            printError("剧情过场不存在该类型  type =====  "..vo.type)
        end
    else
        KTool.SetActive(self.FirstPhase.gameObject,false)
        KTool.SetActive(self.SecondPhase.gameObject,false)
        printError("剧情过场 【A倒计时文本表】 Id ===== %s  不存在 请检查！！",vo.sceneId)
    end
end

function ChapterLoading:SetTextDay(day)
    if day then
        if checkNumber(day) > 1 then
            CfUtils.SetUISwitchText(self.TextDay,2)
        else
            CfUtils.SetUISwitchText(self.TextDay,1)
        end
    end
end

function ChapterLoading:StopCo()
    if self.changeCo ~= nil then
        cs_coroutine.stop(self.changeCo)
        self.changeCo = nil
    end
end

function ChapterLoading:SetRandomTime()
    for i = 1, randomTimeCount do
        local randomTime = self["RandomTime"..i]
        if randomTime then
            local time = self:GetRandomTime()
            CfUtils.FillText(randomTime,time)
        end
    end
end

function ChapterLoading:GetRandomTime()
    local hour = math.random(1,24)
    if hour < 10 then
        hour = "0"..hour
    end
    local min = math.random(1,60)
    if min < 10 then
        min = "0"..min
    end

    local sec = math.random(1,60)
    if sec < 10 then
        sec = "0"..sec
    end

    return string.format("%s:%s:%s",hour,min,sec)
end

function ChapterLoading:RandomPos()

end

function ChapterLoading:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self.LoadingVo = nil
    self:StopCo()
    self:Delete()
end

return ChapterLoading